-- =============================================================================
-- 0025_ganesha_missing_steps.sql
--
-- GENERATED by scripts/build-ganesha-missing-steps.mjs. Do not hand-edit.
--
-- The book’s purvangam has eighteen numbered steps. This pooja had seven.
-- Thirteen are added and the order becomes the book’s: 24 steps -> 37.
--
-- The largest gap was the preliminary Vighneshwara Pooja, a complete rite with
-- its own upacharas, sixteen-name archana, naivedyam and camphor, performed
-- before every important act. The app’s flagship GANESHA pooja skipped it.
--
-- Reordering matters as much: the book puts Ghanta Pooja before the preliminary
-- rite and Kalasha Pooja AFTER the main sankalpam. 0024 gave that sankalpam the
-- tail "tadangam kalasha poojam cha karishye" -- and as a limb of this I shall
-- also perform the kalasha pooja -- which only parses if the kalasha pooja
-- follows it. It now does.
--
-- Idempotent: inserts are guarded on the natural key, and the renumber is a
-- straight assignment rather than an increment.
-- =============================================================================

begin;

-- --- 0. enforce the natural key ----------------------------------------------
-- Every migration in this project addresses a step by (pooja_id,
-- step_title_en) -- uuids differ per environment, so they have never been
-- usable -- and the database has never enforced it. That is why this migration
-- cannot use ON CONFLICT without adding it first, and it is worth adding on its
-- own account: two rows sharing a title would silently make every later
-- migration update the wrong one, or both. Verified clean on 53 rows before
-- this was written.
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'pooja_steps_pooja_title_uk'
  ) then
    alter table public.pooja_steps
      add constraint pooja_steps_pooja_title_uk unique (pooja_id, step_title_en);
  end if;
end $$;

-- --- 1. park every existing number out of the way ----------------------------
-- The unique constraint on (pooja_id, step_number) makes an in-place shuffle
-- impossible: some intermediate state always has two rows on one number.
update public.pooja_steps set step_number = step_number + 1000
 where pooja_id = 'ganesha_standard' and step_number < 1000;

-- --- 2. the new steps ---------------------------------------------------------
-- 5 Vighneshwara Sankalpam
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
