  instruction_en = excluded.instruction_en,
  instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit,
  mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit,
  variant_mantra_sanskrit = excluded.variant_mantra_sanskrit,
  variant_note_en = excluded.variant_note_en,
  meaning_en = excluded.meaning_en,
  source_ref = excluded.source_ref,
  modes = excluded.modes,
  updated_at = now();

-- 11 Vighneshwara Shodasha Nama Archana
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   variant_mantra_sanskrit, variant_note_en, meaning_en, source_ref, gender_rule, modes)
values (
  'ganesha_standard', 11, 'Vighneshwara Shodasha Nama Archana', 'விக்னேஸ்வர ஷோடஶ நாம அர்ச்சனை', 'purvangam',
  'Offer a flower, or a blade of arugampul, at each of the sixteen names. Durva is preferred to any flower for Ganesha.',
  'பதினாறு நாமங்கள் ஒவ்வொன்றிலும் ஒரு பூ அல்லது ஒரு அருகம்புல் இதழ் சமர்ப்பிக்கவும். விநாயகருக்குப் பூவை விட அருகம்புல்லே உகந்தது.',
  null,
  null,
  null,
  null, null,
  'The sixteen names of Ganesha recited at the preliminary pooja: fair-faced, single-tusked, tawny, elephant-eared, pot-bellied, formidable, king over obstacles, the remover, the comet-bannered, chief of the ganas, moon-browed, elephant-faced, curve-trunked, winnow-eared, Heramba, and elder brother of Skanda.', 'Sampradaya Vratha Pooja Vidhi (Giri), purvanga pooja pp.9-10, step 8. Transcribed from a photograph of the printed page, so unlike the round-tripped sources in this project it carries no reversibility proof. Tamil instruction prose is this project’s own drafting, not the book’s, and is the least reviewed text here.', 'all', '{main,punar}'::text[]
)
on conflict (pooja_id, step_title_en) do update set
  step_number = excluded.step_number,
  step_title_ta = excluded.step_title_ta,
  phase = excluded.phase,
  instruction_en = excluded.instruction_en,
  instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit,
  mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit,
  variant_mantra_sanskrit = excluded.variant_mantra_sanskrit,
  variant_note_en = excluded.variant_note_en,
  meaning_en = excluded.meaning_en,
  source_ref = excluded.source_ref,
  modes = excluded.modes,
  updated_at = now();

-- Vighneshwara Shodasha Nama Archana: 16 offerings
delete from public.archana_items a using public.pooja_steps s
 where a.pooja_step_id = s.id and s.pooja_id = 'ganesha_standard'
   and s.step_title_en = 'Vighneshwara Shodasha Nama Archana';
insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit,
   offering_deva, offering_en, offering_ta, meaning_en)
select s.id, v.seq, v.deva, v.ta, v.iast,
       'पुष्पैः पूजयामि', 'Offer a flower or a blade of durva', 'ஒரு பூ அல்லது அருகம்புல் சமர்ப்பிக்கவும்', v.meaning
  from public.pooja_steps s, (values
    (1, 'ॐ सुमुखाय नमः', 'ஓம் ஸுமுகாய நம꞉', 'oṃ sumukhāya namaḥ', 'To the fair-faced one'),
    (2, 'ॐ एकदन्ताय नमः', 'ஓம் ஏகதந்தாய நம꞉', 'oṃ ekadantāya namaḥ', 'To the single-tusked one'),
    (3, 'ॐ कपिलाय नमः', 'ஓம் கபிலாய நம꞉', 'oṃ kapilāya namaḥ', 'To the tawny one'),
    (4, 'ॐ गजकर्णकाय नमः', 'ஓம் கஜகர்ணகாய நம꞉', 'oṃ gajakarṇakāya namaḥ', 'To the elephant-eared one'),
    (5, 'ॐ लम्बोदराय नमः', 'ஓம் லம்போதராய நம꞉', 'oṃ lambodarāya namaḥ', 'To the pot-bellied one'),
    (6, 'ॐ विकटाय नमः', 'ஓம் விகடாய நம꞉', 'oṃ vikaṭāya namaḥ', 'To the formidable one'),
    (7, 'ॐ विघ्नराजाय नमः', 'ஓம் விக்நராஜாய நம꞉', 'oṃ vighnarājāya namaḥ', 'To the king over obstacles'),
    (8, 'ॐ विनायकाय नमः', 'ஓம் விநாயகாய நம꞉', 'oṃ vināyakāya namaḥ', 'To the remover'),
    (9, 'ॐ धूमकेतवे नमः', 'ஓம் தூமகேதவே நம꞉', 'oṃ dhūmaketave namaḥ', 'To the comet-bannered one'),
    (10, 'ॐ गणाध्यक्षाय नमः', 'ஓம் கணாத்யக்ஷாய நம꞉', 'oṃ gaṇādhyakṣāya namaḥ', 'To the chief of the ganas'),
    (11, 'ॐ फालचन्द्राय नमः', 'ஓம் பாலசந்த்ராய நம꞉', 'oṃ phālacandrāya namaḥ', 'To him who wears the moon on his brow'),
    (12, 'ॐ गजाननाय नमः', 'ஓம் கஜாநநாய நம꞉', 'oṃ gajānanāya namaḥ', 'To the elephant-faced one'),
    (13, 'ॐ वक्रतुण्डाय नमः', 'ஓம் வக்ரதுண்டாய நம꞉', 'oṃ vakratuṇḍāya namaḥ', 'To the curve-trunked one'),
    (14, 'ॐ शूर्पकर्णाय नमः', 'ஓம் ஶூர்பகர்ணாய நம꞉', 'oṃ śūrpakarṇāya namaḥ', 'To the winnow-eared one'),
    (15, 'ॐ हेरम्बाय नमः', 'ஓம் ஹேரம்பாய நம꞉', 'oṃ herambāya namaḥ', 'To Heramba'),
    (16, 'ॐ स्कन्दपूर्वजाय नमः', 'ஓம் ஸ்கந்தபூர்வஜாய நம꞉', 'oṃ skandapūrvajāya namaḥ', 'To the elder brother of Skanda')
  ) as v(seq, deva, ta, iast, meaning)
 where s.pooja_id = 'ganesha_standard' and s.step_title_en = 'Vighneshwara Shodasha Nama Archana';

-- 12 Vighneshwara Naivedyam & Neerajanam
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   variant_mantra_sanskrit, variant_note_en, meaning_en, source_ref, gender_rule, modes)
values (
  'ganesha_standard', 12, 'Vighneshwara Naivedyam & Neerajanam', 'மஹாகணபதயே நம꞉ நாநாவித பரிமல பத்ர புஷ்பாணி ஸமர்பயாமி ।
தூபமாக்ராபயாமி, தீபம் தர்ஶயாமி ।
தூப தீபாநந்தரம் ஆசமநீயம் ஸமர்பயாமி ।
ஓம் பூர்புவஸ்ஸுவ꞉ ।
தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி, தியோ யோ ந꞉ ப்ரசோதயாத் ।
தேவஸவித꞉ ப்ரஸுவ । ஸத்யம் த்வர்தேந பரிஷிஞ்சாமி ।
அம்ருதோபஸ்தரணமஸி ।
ஓம் ப்ராணாய ஸ்வாஹா । ஓம் அபாநாய ஸ்வாஹா ।
ஓம் வ்யாநாய ஸ்வாஹா । ஓம் உதாநாய ஸ்வாஹா ।
ஓம் ஸமாநாய ஸ்வாஹா । ஓம் ப்ரஹ்மணே ஸ்வாஹா ।
மத்யே மத்யே அம்ருதபாநீயம் ஸமர்பயாமி ।
அம்ருதாபிதாநமஸி । ஆசமநீயம் ஸமர்பயாமி ।
உத்தராபோஶநம் ஸமர்பயாமி ।
கர்பூரநீராஜநம் ஸந்தர்ஶயாமி ।', 'purvangam',
  'Offer incense and wave the ghee lamp. Then place the naivedyam — a fruit or a piece of jaggery is enough for this preliminary rite — sprinkle water over it, circle water around the plate clockwise three times, and make the six offerings, gesturing with the right hand as if feeding the deity at each "svaha". Finish by waving camphor clockwise.',
  'தூபம் காட்டி, நெய் தீபம் ஏற்றிக் காட்டவும். பிறகு நைவேத்யத்தை — இந்தச் சிறு பூஜைக்கு ஒரு பழமோ சிறிது வெல்லமோ போதும் — வைத்து, அதன் மீது நீர் தெளித்து, தட்டைச் சுற்றி மூன்று முறை வலம் வரும்படி நீர் சுற்றவும். ஒவ்வொரு "ஸ்வாஹா"விலும் வலக்கையால் ஊட்டுவது போல் சைகை செய்யவும். இறுதியில் கற்பூரம் ஏற்றி வலமாகச் சுற்றிக் காட்டவும்.',
  'महागणपतये नमः नानाविध परिमल पत्र पुष्पाणि समर्पयामि ।
धूपमाघ्रापयामि, दीपं दर्शयामि ।
धूप दीपानन्तरं आचमनीयं समर्पयामि ।
ॐ भूर्भुवस्सुवः ।
तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि, धियो यो नः प्रचोदयात् ।
देवसवितः प्रसुव । सत्यं त्वर्तेन परिषिञ्चामि ।
अमृतोपस्तरणमसि ।
ॐ प्राणाय स्वाहा । ॐ अपानाय स्वाहा ।
ॐ व्यानाय स्वाहा । ॐ उदानाय स्वाहा ।
ॐ समानाय स्वाहा । ॐ ब्रह्मणे स्वाहा ।
मध्ये मध्ये अमृतपानीयं समर्पयामि ।
अमृतापिधानमसि । आचमनीयं समर्पयामि ।
उत्तरापोशनम् समर्पयामि ।
कर्पूरनीराजनं सन्दर्शयामि ।',
  'மஹாகணபதயே நம꞉ நாநாவித பரிமல பத்ர புஷ்பாணி ஸமர்பயாமி ।
தூபமாக்ராபயாமி, தீபம் தர்ஶயாமி ।
தூப தீபாநந்தரம் ஆசமநீயம் ஸமர்பயாமி ।
ஓம் பூர்புவஸ்ஸுவ꞉ ।
தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி, தியோ யோ ந꞉ ப்ரசோதயாத் ।
தேவஸவித꞉ ப்ரஸுவ । ஸத்யம் த்வர்தேந பரிஷிஞ்சாமி ।
அம்ருதோபஸ்தரணமஸி ।
ஓம் ப்ராணாய ஸ்வாஹா । ஓம் அபாநாய ஸ்வாஹா ।
ஓம் வ்யாநாய ஸ்வாஹா । ஓம் உதாநாய ஸ்வாஹா ।
ஓம் ஸமாநாய ஸ்வாஹா । ஓம் ப்ரஹ்மணே ஸ்வாஹா ।
மத்யே மத்யே அம்ருதபாநீயம் ஸமர்பயாமி ।
அம்ருதாபிதாநமஸி । ஆசமநீயம் ஸமர்பயாமி ।
உத்தராபோஶநம் ஸமர்பயாமி ।
கர்பூரநீராஜநம் ஸந்தர்ஶயாமி ।',
  'mahāgaṇapataye namaḥ nānāvidha parimala patra puṣpāṇi samarpayāmi ।
dhūpamāghrāpayāmi, dīpaṃ darśayāmi ।
dhūpa dīpānantaraṃ ācamanīyaṃ samarpayāmi ।
oṃ bhūrbhuvassuvaḥ ।
tatsaviturvareṇyaṃ bhargo devasya dhīmahi, dhiyo yo naḥ pracodayāt ।
devasavitaḥ prasuva । satyaṃ tvartena pariṣiñcāmi ।
amṛtopastaraṇamasi ।
oṃ prāṇāya svāhā । oṃ apānāya svāhā ।
oṃ vyānāya svāhā । oṃ udānāya svāhā ।
oṃ samānāya svāhā । oṃ brahmaṇe svāhā ।
madhye madhye amṛtapānīyaṃ samarpayāmi ।
amṛtāpidhānamasi । ācamanīyaṃ samarpayāmi ।
uttarāpośanam samarpayāmi ।
karpūranīrājanaṃ sandarśayāmi ।',
  'देवसवितः प्रसुव । ऋतं त्वा सत्येन परिषिञ्चामि ।', 'Recited in place of the morning line when the pooja is performed in the evening. The book prints the two forms side by side, labelled (Morning) and (Evening).',
  'I offer fragrant leaves and flowers of many kinds. I offer incense and show the lamp, and water to sip after them. Then the vyahritis, the Gayatri, and the offering of the food to the five breaths and to Brahman, water in between, and finally the camphor light.', 'Sampradaya Vratha Pooja Vidhi (Giri), purvanga pooja pp.10-12, step 8. Transcribed from a photograph of the printed page, so unlike the round-tripped sources in this project it carries no reversibility proof. Tamil instruction prose is this project’s own drafting, not the book’s, and is the least reviewed text here.', 'all', '{main,punar}'::text[]
)
on conflict (pooja_id, step_title_en) do update set
  step_number = excluded.step_number,
  step_title_ta = excluded.step_title_ta,
  phase = excluded.phase,
  instruction_en = excluded.instruction_en,
  instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit,
  mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit,
  variant_mantra_sanskrit = excluded.variant_mantra_sanskrit,
  variant_note_en = excluded.variant_note_en,
  meaning_en = excluded.meaning_en,
  source_ref = excluded.source_ref,
  modes = excluded.modes,
  updated_at = now();

-- 14 Vighneshwara Udvasanam
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   variant_mantra_sanskrit, variant_note_en, meaning_en, source_ref, gender_rule, modes)
values (
  'ganesha_standard', 14, 'Vighneshwara Udvasanam', 'வக்ரதுண்ட மஹாகாய கோடிஸூர்யஸமப்ரப ।
நிர்விக்நம் குரு மே தேவ ஸர்வகார்யேஷு ஸர்வதா ॥
ஶ்ரீ விக்நேஶ்வரம் யதாஸ்தாநம் ப்ரதிஷ்டாபயாமி,
ஶோபநார்தே க்ஷேமாய புநராகமநாய ச ।
விக்நேஶ்வர ப்ரஸாதம் ஶிரஸா க்ருஹ்ணாமி ॥', 'purvangam',
  'The obstacle-removing rite is complete, so its Ganesha is sent back. Move the turmeric cone a little towards the north. Receive the flowers that were offered to it, touch them to your eyes and place them on your head, or give them to the women of the household. Then take water in the uddharani and wash the hands.',
  'தடை நீக்கும் பூஜை முடிந்ததால், அந்த விநாயகரை யதாஸ்தானம் செய்யவும். மஞ்சள் கூம்பைச் சிறிது வடக்கு நோக்கி நகர்த்தவும். சமர்ப்பித்த பூக்களைப் பக்தியுடன் பெற்று, கண்களில் ஒற்றி, தலையில் வைக்கவும், அல்லது வீட்டுப் பெண்களுக்குக் கொடுக்கவும். பிறகு உத்தரணியில் நீர் எடுத்துக் கைகளைக் கழுவவும்.',
  'वक्रतुण्ड महाकाय कोटिसूर्यसमप्रभ ।
निर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा ॥
श्री विघ्नेश्वरं यथास्थानं प्रतिष्ठापयामि,
शोभनार्थे क्षेमाय पुनरागमनाय च ।
विघ्नेश्वर प्रसादं शिरसा गृह्णामि ॥',
  'வக்ரதுண்ட மஹாகாய கோடிஸூர்யஸமப்ரப ।
நிர்விக்நம் குரு மே தேவ ஸர்வகார்யேஷு ஸர்வதா ॥
ஶ்ரீ விக்நேஶ்வரம் யதாஸ்தாநம் ப்ரதிஷ்டாபயாமி,
ஶோபநார்தே க்ஷேமாய புநராகமநாய ச ।
விக்நேஶ்வர ப்ரஸாதம் ஶிரஸா க்ருஹ்ணாமி ॥',
  'vakratuṇḍa mahākāya koṭisūryasamaprabha ।
nirvighnaṃ kuru me deva sarvakāryeṣu sarvadā ॥
śrī vighneśvaraṃ yathāsthānaṃ pratiṣṭhāpayāmi,
śobhanārthe kṣemāya punarāgamanāya ca ।
vighneśvara prasādaṃ śirasā gṛhṇāmi ॥',
  null, null,
  'Curve-trunked, mighty-bodied, bright as a crore of suns: make all my undertakings free of obstacles, always. I establish Sri Vighneshwara back in his own place, for grace, for wellbeing, and so that he may come again. I receive his prasadam upon my head.', 'Sampradaya Vratha Pooja Vidhi (Giri), purvanga pooja p.14, step 11. Transcribed from a photograph of the printed page, so unlike the round-tripped sources in this project it carries no reversibility proof. Tamil instruction prose is this project’s own drafting, not the book’s, and is the least reviewed text here.', 'all', '{main,punar}'::text[]
)
on conflict (pooja_id, step_title_en) do update set
  step_number = excluded.step_number,
  step_title_ta = excluded.step_title_ta,
  phase = excluded.phase,
  instruction_en = excluded.instruction_en,
  instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit,
  mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit,
  variant_mantra_sanskrit = excluded.variant_mantra_sanskrit,
  variant_note_en = excluded.variant_note_en,
  meaning_en = excluded.meaning_en,
  source_ref = excluded.source_ref,
  modes = excluded.modes,
  updated_at = now();

-- 16 Shankha Pooja
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   variant_mantra_sanskrit, variant_note_en, meaning_en, source_ref, gender_rule, modes)
values (
  'ganesha_standard', 16, 'Shankha Pooja', 'ஶங்கம் சந்த்ரார்க தைவத்யம் மத்யே வருண தைவதம் ।
ப்ருஷ்டே ப்ரஜாபதி வித்யாத் அக்ரே கங்கா ஸரஸ்வதீ ॥
த்வம் புரா ஸாகரோத்பந்ந꞉ விஷ்ணுநா வித்ருத꞉ கரே ।
பூஜித꞉ ஸர்வ தேவைஶ்ச பாஞ்சஜந்ய நமோஸ்து தே ॥
த்ரைலோக்யே யாநி தீர்தாநி வாஸுதேவஸ்ய ச ஆஜ்ஞயா ।
ஶங்கே திஷ்டந்தி விப்ரேந்த்ர தஸ்மாச்சங்கம் ப்ரபூஜயேத் ॥
பாஞ்சஜந்யாய வித்மஹே பவமாநாய தீமஹி ।
தந்ந꞉ ஶங்க꞉ ப்ரசோதயாத் ॥
ஶங்காய நம꞉ । பர்ஜந்யாய நம꞉ । பாஞ்சஜந்யாய நம꞉ ।
அம் அர்கமண்டலாய நம꞉ । ரம் வஹ்நிமண்டலாய நம꞉ ।
ஸம் ஸோமமண்டலாய நம꞉ । ஸப்தகோடி மஹாதீர்தேப்யோ நம꞉ ।
ஶங்கராஜாய நம꞉ । ஸமஸ்தோபசாராந் ஸமர்பயாமி ॥', 'purvangam',
  'SKIP THIS STEP IF THERE IS NO CONCH IN THE HOUSE — the book says so plainly, while adding that it is worth keeping at least a small one, since the conch stands for the pranava and is a dwelling of Lakshmi. Set the conch on a firm stand, anoint it with sandal paste and kumkumam, and fill it with water from the panchapatra while saying the Gayatri or Om three times. After the mantras, sprinkle every article set aside for the pooja with water from the conch, then refill it.',
  'வீட்டில் ஶங்கு இல்லையென்றால் இந்தப் படியைத் தவிர்க்கலாம் — புத்தகமே இதைத் தெளிவாகச் சொல்கிறது. ஆயினும் ஶங்கு ப்ரணவத்தைக் குறிப்பதாலும் லக்ஷ்மியின் இருப்பிடம் என்பதாலும் சிறியதாவது வைத்திருப்பது நல்லது. ஶங்கை உறுதியான பீடத்தில் வைத்து, சந்தனமும் குங்குமமும் இட்டு, காயத்ரி அல்லது ஓம் மூன்று முறை சொல்லிப் பஞ்சபாத்திரத்திலிருந்து நீர் நிரப்பவும். மந்திரங்களுக்குப் பிறகு, பூஜைக்கு வைத்துள்ள பொருட்கள் அனைத்தின் மீதும் ஶங்கு நீரைத் தெளித்து, மீண்டும் நிரப்பவும்.',
  'शङ्खं चन्द्रार्क दैवत्यं मध्ये वरुण दैवतम् ।
पृष्ठे प्रजापति विद्यात् अग्रे गङ्गा सरस्वती ॥
त्वं पुरा सागरोत्पन्नः विष्णुना विधृतः करे ।
पूजितः सर्व देवैश्च पाञ्चजन्य नमोऽस्तु ते ॥
त्रैलोक्ये यानि तीर्थानि वासुदेवस्य च आज्ञया ।
शङ्खे तिष्ठन्ति विप्रेन्द्र तस्माच्छङ्खं प्रपूजयेत् ॥
पाञ्चजन्याय विद्महे पवमानाय धीमहि ।
तन्नः शङ्खः प्रचोदयात् ॥
शङ्खाय नमः । पर्जन्याय नमः । पाञ्चजन्याय नमः ।
अं अर्कमण्डलाय नमः । रं वह्निमण्डलाय नमः ।
सं सोममण्डलाय नमः । सप्तकोटि महातीर्थेभ्यो नमः ।
शङ्खराजाय नमः । समस्तोपचारान् समर्पयामि ॥',
  'ஶங்கம் சந்த்ரார்க தைவத்யம் மத்யே வருண தைவதம் ।
ப்ருஷ்டே ப்ரஜாபதி வித்யாத் அக்ரே கங்கா ஸரஸ்வதீ ॥
த்வம் புரா ஸாகரோத்பந்ந꞉ விஷ்ணுநா வித்ருத꞉ கரே ।
பூஜித꞉ ஸர்வ தேவைஶ்ச பாஞ்சஜந்ய நமோஸ்து தே ॥
த்ரைலோக்யே யாநி தீர்தாநி வாஸுதேவஸ்ய ச ஆஜ்ஞயா ।
ஶங்கே திஷ்டந்தி விப்ரேந்த்ர தஸ்மாச்சங்கம் ப்ரபூஜயேத் ॥
பாஞ்சஜந்யாய வித்மஹே பவமாநாய தீமஹி ।
தந்ந꞉ ஶங்க꞉ ப்ரசோதயாத் ॥
ஶங்காய நம꞉ । பர்ஜந்யாய நம꞉ । பாஞ்சஜந்யாய நம꞉ ।
அம் அர்கமண்டலாய நம꞉ । ரம் வஹ்நிமண்டலாய நம꞉ ।
ஸம் ஸோமமண்டலாய நம꞉ । ஸப்தகோடி மஹாதீர்தேப்யோ நம꞉ ।
ஶங்கராஜாய நம꞉ । ஸமஸ்தோபசாராந் ஸமர்பயாமி ॥',
  'śaṅkhaṃ candrārka daivatyaṃ madhye varuṇa daivatam ।
pṛṣṭhe prajāpati vidyāt agre gaṅgā sarasvatī ॥
tvaṃ purā sāgarotpannaḥ viṣṇunā vidhṛtaḥ kare ।
pūjitaḥ sarva devaiśca pāñcajanya namo''stu te ॥
trailokye yāni tīrthāni vāsudevasya ca ājñayā ।
śaṅkhe tiṣṭhanti viprendra tasmācchaṅkhaṃ prapūjayet ॥
pāñcajanyāya vidmahe pavamānāya dhīmahi ।
tannaḥ śaṅkhaḥ pracodayāt ॥
śaṅkhāya namaḥ । parjanyāya namaḥ । pāñcajanyāya namaḥ ।
aṃ arkamaṇḍalāya namaḥ । raṃ vahnimaṇḍalāya namaḥ ।
saṃ somamaṇḍalāya namaḥ । saptakoṭi mahātīrthebhyo namaḥ ।
śaṅkharājāya namaḥ । samastopacārān samarpayāmi ॥',
  null, null,
  'The conch has the sun and moon for its deity, Varuna at its middle, Prajapati at its back, and Ganga and Sarasvati at its mouth. You rose long ago from the ocean and were held in Vishnu’s hand, worshipped by all the gods: salutation to you, Panchajanya. By Vasudeva’s command, every sacred water in the three worlds abides in the conch; therefore let the conch be worshipped.', 'Sampradaya Vratha Pooja Vidhi (Giri), purvanga pooja pp.16-17, step 13. Transcribed from a photograph of the printed page, so unlike the round-tripped sources in this project it carries no reversibility proof. Tamil instruction prose is this project’s own drafting, not the book’s, and is the least reviewed text here.', 'all', '{main,punar}'::text[]
)
