-- 17 Atma Pooja
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   variant_mantra_sanskrit, variant_note_en, meaning_en, source_ref, gender_rule, modes)
values (
  'ganesha_standard', 17, 'Atma Pooja', 'தேஹோ தேவாலய꞉ ப்ரோக்த꞉ ஜீவோ தேவ꞉ ஸநாதந꞉ ।
த்யஜேதஜ்ஞாந நிர்மால்யம் ஸோஹம் பாவேந பூஜயேத் ॥', 'purvangam',
  'Turn the mind inward for a few seconds, holding that the self dwelling within pervades the world and is one in essence with the supreme Self. Then place a little akshatai on your own head, as an act of worshipping yourself.',
  'சில வினாடிகள் மனதை உள்நோக்கித் திருப்பி, உள்ளே உறையும் ஆத்மா உலகெங்கும் நிறைந்தது என்றும், பரமாத்மாவுடன் ஒன்றே என்றும் நினைக்கவும். பிறகு உங்கள் தலையிலேயே சிறிது அட்சதை இட்டுக்கொள்ளவும் — அது தன்னைத் தானே பூஜிக்கும் செயல்.',
  'देहो देवालयः प्रोक्तः जीवो देवः सनातनः ।
त्यजेदज्ञान निर्माल्यं सोऽहं भावेन पूजयेत् ॥',
  'தேஹோ தேவாலய꞉ ப்ரோக்த꞉ ஜீவோ தேவ꞉ ஸநாதந꞉ ।
த்யஜேதஜ்ஞாந நிர்மால்யம் ஸோஹம் பாவேந பூஜயேத் ॥',
  'deho devālayaḥ proktaḥ jīvo devaḥ sanātanaḥ ।
tyajedajñāna nirmālyaṃ so''haṃ bhāvena pūjayet ॥',
  null, null,
  'The body is called a temple; the living self is the eternal deity. Cast away the withered flowers of ignorance, and worship with the thought "I am That."', 'Sampradaya Vratha Pooja Vidhi (Giri), purvanga pooja p.18, step 14. Transcribed from a photograph of the printed page, so unlike the round-tripped sources in this project it carries no reversibility proof. Tamil instruction prose is this project’s own drafting, not the book’s, and is the least reviewed text here.', 'all', '{main,punar}'::text[]
)
on conflict (pooja_id, step_title_en) do update set
  step_number = excluded.step_number,
  step_title_ta = excluded.step_title_ta,
  phase = excluded.phase,
  instruction_en = excluded.instruction_en,
  instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit,
  mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit,
  variant_mantra_sanskrit = excluded.variant_mantra_sanskrit,
  variant_note_en = excluded.variant_note_en,
  meaning_en = excluded.meaning_en,
  source_ref = excluded.source_ref,
  modes = excluded.modes,
  updated_at = now();

-- 18 Peetha Pooja
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   variant_mantra_sanskrit, variant_note_en, meaning_en, source_ref, gender_rule, modes)
values (
  'ganesha_standard', 18, 'Peetha Pooja', 'ஓம் ஆதாரஶக்த்யை நம꞉ ।
ஓம் மூலப்ரக்ருத்யை நம꞉ ।
ஓம் ஆதி கூர்மாய நம꞉ ।
ஓம் ஆதி வராஹாய நம꞉ ।
ஓம் அநந்தாய நம꞉ ।
ஓம் ப்ருதிவ்யை நம꞉ ।
ஓம் ரத்நமண்டபாய நம꞉ ।
ஓம் ரத்நவேதிகாயை நம꞉ ।
ஓம் ஸ்வர்ண ஸ்தம்பாய நம꞉ ।
ஓம் ஶ்வேதச்சத்ராய நம꞉ ।
ஓம் கல்பக வ்ருக்ஷாய நம꞉ ।
ஓம் க்ஷீர ஸமுத்ராய நம꞉ ।
ஓம் ஸித சாமராப்யாம் நம꞉ ।
ஓம் யோகபீடாஸநாய நம꞉ ॥', 'purvangam',
  'Worship the seat on which the deity will be enshrined, offering a flower and akshatai at each name. The fourteen names build the seat upward from the power that holds everything, through the tortoise and the boar and the earth, to the jewelled pavilion, the golden pillar, the white parasol, the wish-giving tree, the ocean of milk, the two white whisks, and last the yoga seat itself.',
  'தெய்வம் எழுந்தருளப் போகும் பீடத்தைப் பூஜிக்கவும்; ஒவ்வொரு நாமத்திலும் ஒரு பூவும் அட்சதையும் சமர்ப்பிக்கவும். இந்தப் பதினான்கு நாமங்கள் அனைத்தையும் தாங்கும் ஆதாரசக்தியிலிருந்து தொடங்கி, கூர்மம், வராகம், பூமி வழியாக, ரத்ன மண்டபம், ஸ்வர்ண ஸ்தம்பம், வெண்குடை, கற்பக விருக்ஷம், க்ஷீர ஸமுத்திரம், வெண் சாமரங்கள், இறுதியாக யோக பீடாஸனம் வரை பீடத்தைக் கட்டுகின்றன.',
  'ॐ आधारशक्त्यै नमः ।
ॐ मूलप्रकृत्यै नमः ।
ॐ आदि कूर्माय नमः ।
ॐ आदि वराहाय नमः ।
ॐ अनन्ताय नमः ।
ॐ पृथिव्यै नमः ।
ॐ रत्नमण्डपाय नमः ।
ॐ रत्नवेदिकायै नमः ।
ॐ स्वर्ण स्तम्भाय नमः ।
ॐ श्वेतच्छत्राय नमः ।
ॐ कल्पक वृक्षाय नमः ।
ॐ क्षीर समुद्राय नमः ।
ॐ सित चामराभ्यां नमः ।
ॐ योगपीठासनाय नमः ॥',
  'ஓம் ஆதாரஶக்த்யை நம꞉ ।
ஓம் மூலப்ரக்ருத்யை நம꞉ ।
ஓம் ஆதி கூர்மாய நம꞉ ।
ஓம் ஆதி வராஹாய நம꞉ ।
ஓம் அநந்தாய நம꞉ ।
ஓம் ப்ருதிவ்யை நம꞉ ।
ஓம் ரத்நமண்டபாய நம꞉ ।
ஓம் ரத்நவேதிகாயை நம꞉ ।
ஓம் ஸ்வர்ண ஸ்தம்பாய நம꞉ ।
ஓம் ஶ்வேதச்சத்ராய நம꞉ ।
ஓம் கல்பக வ்ருக்ஷாய நம꞉ ।
ஓம் க்ஷீர ஸமுத்ராய நம꞉ ।
ஓம் ஸித சாமராப்யாம் நம꞉ ।
ஓம் யோகபீடாஸநாய நம꞉ ॥',
  'oṃ ādhāraśaktyai namaḥ ।
oṃ mūlaprakṛtyai namaḥ ।
oṃ ādi kūrmāya namaḥ ।
oṃ ādi varāhāya namaḥ ।
oṃ anantāya namaḥ ।
oṃ pṛthivyai namaḥ ।
oṃ ratnamaṇḍapāya namaḥ ।
oṃ ratnavedikāyai namaḥ ।
oṃ svarṇa stambhāya namaḥ ।
oṃ śvetacchatrāya namaḥ ।
oṃ kalpaka vṛkṣāya namaḥ ।
oṃ kṣīra samudrāya namaḥ ।
oṃ sita cāmarābhyāṃ namaḥ ।
oṃ yogapīṭhāsanāya namaḥ ॥',
  null, null,
  'Salutation to the supporting power, to primordial nature, to the first tortoise, to the first boar, to Ananta, to the earth, to the jewelled pavilion, to the jewelled altar, to the golden pillar, to the white parasol, to the wish-giving tree, to the ocean of milk, to the two white whisks, and to the seat of yoga.', 'Sampradaya Vratha Pooja Vidhi (Giri), purvanga pooja pp.18-19, step 15. Transcribed from a photograph of the printed page, so unlike the round-tripped sources in this project it carries no reversibility proof. Tamil instruction prose is this project’s own drafting, not the book’s, and is the least reviewed text here.', 'all', '{main,punar}'::text[]
)
on conflict (pooja_id, step_title_en) do update set
  step_number = excluded.step_number,
  step_title_ta = excluded.step_title_ta,
  phase = excluded.phase,
  instruction_en = excluded.instruction_en,
  instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit,
  mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit,
  variant_mantra_sanskrit = excluded.variant_mantra_sanskrit,
  variant_note_en = excluded.variant_note_en,
  meaning_en = excluded.meaning_en,
  source_ref = excluded.source_ref,
  modes = excluded.modes,
  updated_at = now();

-- 19 Guru Dhyanam
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   variant_mantra_sanskrit, variant_note_en, meaning_en, source_ref, gender_rule, modes)
values (
  'ganesha_standard', 19, 'Guru Dhyanam', 'குருர்ப்ரஹ்மா குருர்விஷ்ணு꞉ குருர்தேவோ மஹேஶ்வர꞉ ।
குருஸ்ஸாக்ஷாத் பரம் ப்ரஹ்ம தஸ்மை ஶ்ரீ குரவே நம꞉ ॥', 'purvangam',
  'Contemplate your own teacher, as your family tradition holds. This is the last step before the deity is meditated upon and invoked.',
  'உங்கள் குடும்ப மரபின்படி உங்கள் குருவை த்யானிக்கவும். தெய்வத்தை த்யானித்து ஆவாஹனம் செய்வதற்கு முந்தைய கடைசிப் படி இது.',
  'गुरुर्ब्रह्मा गुरुर्विष्णुः गुरुर्देवो महेश्वरः ।
गुरुस्साक्षात् परं ब्रह्म तस्मै श्री गुरवे नमः ॥',
  'குருர்ப்ரஹ்மா குருர்விஷ்ணு꞉ குருர்தேவோ மஹேஶ்வர꞉ ।
குருஸ்ஸாக்ஷாத் பரம் ப்ரஹ்ம தஸ்மை ஶ்ரீ குரவே நம꞉ ॥',
  'gururbrahmā gururviṣṇuḥ gururdevo maheśvaraḥ ।
gurussākṣāt paraṃ brahma tasmai śrī gurave namaḥ ॥',
  null, null,
  'The guru is Brahma, the guru is Vishnu, the guru is the god Maheshwara; the guru is verily the supreme Brahman. To that guru, salutation.', 'Sampradaya Vratha Pooja Vidhi (Giri), purvanga pooja p.19, step 16. Transcribed from a photograph of the printed page, so unlike the round-tripped sources in this project it carries no reversibility proof. Tamil instruction prose is this project’s own drafting, not the book’s, and is the least reviewed text here.', 'all', '{main,punar}'::text[]
)
on conflict (pooja_id, step_title_en) do update set
  step_number = excluded.step_number,
  step_title_ta = excluded.step_title_ta,
  phase = excluded.phase,
  instruction_en = excluded.instruction_en,
  instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit,
  mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit,
  variant_mantra_sanskrit = excluded.variant_mantra_sanskrit,
  variant_note_en = excluded.variant_note_en,
  meaning_en = excluded.meaning_en,
