  modes = excluded.modes,
  updated_at = now();

-- 34 Upayana Danam
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, phase,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   variant_mantra_sanskrit, variant_note_en, meaning_en, source_ref, gender_rule, modes)
values (
  'ganesha_standard', 34, 'Upayana Danam', 'மஹாகணபதி ஸ்வரூபஸ்ய ப்ராஹ்மணஸ்ய இதமாஸநம் ।
அமீதே கந்தா꞉ ஸகலாராதநை꞉ ஸ்வர்சிதம் ॥
கணேஶோ ப்ரதிக்ருஹ்ணாதி கணேஶோ வை ததாதி ச ।
கணேஶஸ்தாரகோத்வாப்யாம் கணேஶாய நமோ நம꞉ ॥
இதம் உபாயநம் ஸதக்ஷிணாகம் ஸதாம்பூலம்
மஹாகணபதி ஸ்வரூபாய ப்ராஹ்மணாய துப்யம் அஹம் ஸம்ப்ரததே ந மம ॥', 'uttara',
  'Give fruit, tambulam and dakshinai either to the priest who performed the pooja or to an elder of the house, after prostrating before them and asking their blessing. Offer them a seat, sandal paste and akshatai first. The words say plainly that the gift is not yours to keep: Ganesha receives it and Ganesha gives it.',
  'பூஜை செய்த புரோகிதருக்கோ, வீட்டின் மூத்தவருக்கோ பழம், தாம்பூலம், தக்ஷிணை ஆகியவற்றை அளிக்கவும். அதற்கு முன் அவர்களை நமஸ்கரித்து ஆசி பெறவும். முதலில் ஆஸனம், சந்தனம், அட்சதை சமர்ப்பிக்கவும். "இது என்னுடையதல்ல" என்று மந்திரமே தெளிவாகச் சொல்கிறது — கணேசரே பெறுகிறார், கணேசரே அளிக்கிறார்.',
  'महागणपति स्वरूपस्य ब्राह्मणस्य इदमासनम् ।
अमीते गन्धाः सकलाराधनैः स्वर्चितम् ॥
गणेशो प्रतिगृह्णाति गणेशो वै ददाति च ।
गणेशस्तारकोद्वाभ्यां गणेशाय नमो नमः ॥
इदं उपायनं सदक्षिणाकं सताम्बूलं
महागणपति स्वरूपाय ब्राह्मणाय तुभ्यं अहं संप्रददे न मम ॥',
  'மஹாகணபதி ஸ்வரூபஸ்ய ப்ராஹ்மணஸ்ய இதமாஸநம் ।
அமீதே கந்தா꞉ ஸகலாராதநை꞉ ஸ்வர்சிதம் ॥
கணேஶோ ப்ரதிக்ருஹ்ணாதி கணேஶோ வை ததாதி ச ।
கணேஶஸ்தாரகோத்வாப்யாம் கணேஶாய நமோ நம꞉ ॥
இதம் உபாயநம் ஸதக்ஷிணாகம் ஸதாம்பூலம்
மஹாகணபதி ஸ்வரூபாய ப்ராஹ்மணாய துப்யம் அஹம் ஸம்ப்ரததே ந மம ॥',
  'mahāgaṇapati svarūpasya brāhmaṇasya idamāsanam ।
amīte gandhāḥ sakalārādhanaiḥ svarcitam ॥
gaṇeśo pratigṛhṇāti gaṇeśo vai dadāti ca ।
gaṇeśastārakodvābhyāṃ gaṇeśāya namo namaḥ ॥
idaṃ upāyanaṃ sadakṣiṇākaṃ satāmbūlaṃ
mahāgaṇapati svarūpāya brāhmaṇāya tubhyaṃ ahaṃ saṃpradade na mama ॥',
  null, null,
  'This seat is for the brahmana who is the very form of Mahaganapati; these fragrances are offered with every act of worship. Ganesha receives and Ganesha gives; Ganesha is on both sides of the crossing. Salutation to Ganesha. This gift, with its dakshinai and its tambulam, I present to you, the brahmana who is the form of Mahaganapati — it is not mine.', 'Sampradaya Vratha Pooja Vidhi (Giri), purvanga pooja p.82. Transcribed from a photograph of the printed page, so unlike the round-tripped sources in this project it carries no reversibility proof. Tamil instruction prose is this project’s own drafting, not the book’s, and is the least reviewed text here.', 'all', '{main,punar}'::text[]
)
on conflict (pooja_id, step_title_en) do update set
  step_number = excluded.step_number,
  step_title_ta = excluded.step_title_ta,
  phase = excluded.phase,
  instruction_en = excluded.instruction_en,
  instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit,
  mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit,
  variant_mantra_sanskrit = excluded.variant_mantra_sanskrit,
  variant_note_en = excluded.variant_note_en,
  meaning_en = excluded.meaning_en,
  source_ref = excluded.source_ref,
  modes = excluded.modes,
  updated_at = now();

-- --- 3. the steps that keep their content and move ---------------------------
