-- --- 4. the second pranayamam, carried in the sankalpam instruction ----------
-- The book performs pranayamam again between the preliminary rite and the main
-- resolve. It cannot be a row of its own: every migration addresses steps by
-- (pooja_id, step_title_en), so a second "Pranayamam" would collide.
update public.pooja_steps set
  instruction_en = 'Perform pranayamam once more before this, holding a little akshatai and touching the right ear with the right hand. Then ' || instruction_en,
  updated_at = now()
 where pooja_id = 'ganesha_standard' and step_title_en = 'Sankalpam'
   and position('Perform pranayamam once more before this, holding a little akshatai and touching the right ear with the right hand. Then ' in instruction_en) = 0;

-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps where pooja_id = 'ganesha_standard';
  if n <> 37 then raise exception 'expected 37 Ganesha steps, found %', n; end if;
  -- Nothing parked, and the numbers are 1..n with no gap and no repeat.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_number >= 1000;
  if n > 0 then raise exception '% Ganesha steps were left parked above 1000', n; end if;
  select (max(step_number) - min(step_number) + 1) - count(*) into n
    from public.pooja_steps where pooja_id = 'ganesha_standard';
  if n <> 0 then raise exception 'Ganesha step numbers are not dense'; end if;
  select count(*) into n from (
    select step_number from public.pooja_steps where pooja_id = 'ganesha_standard'
     group by 1 having count(*) > 1) x;
  if n > 0 then raise exception '% Ganesha step numbers are used twice', n; end if;
  if (select min(step_number) from public.pooja_steps where pooja_id = 'ganesha_standard') <> 1
    then raise exception 'Ganesha steps do not start at 1'; end if;
  -- The preliminary rite exists, and comes before the main resolve.
  select count(*) into n from public.pooja_steps p, public.pooja_steps k
   where p.pooja_id = 'ganesha_standard' and p.step_title_en = 'Vighneshwara Pooja'
     and k.pooja_id = 'ganesha_standard' and k.step_title_en = 'Sankalpam'
     and p.step_number < k.step_number;
  if n <> 1 then raise exception 'the preliminary Vighneshwara pooja is missing or misplaced'; end if;
  -- and the kalasha pooja now follows the sankalpam that announces it.
  select count(*) into n from public.pooja_steps s, public.pooja_steps k
   where s.pooja_id = 'ganesha_standard' and s.step_title_en = 'Sankalpam'
     and k.pooja_id = 'ganesha_standard' and k.step_title_en = 'Kalasha Pooja'
     and k.step_number > s.step_number;
  if n <> 1 then raise exception 'the kalasha pooja does not follow the sankalpam'; end if;
  -- The sixteen names landed.
  select count(*) into n from public.archana_items a join public.pooja_steps s
    on s.id = a.pooja_step_id
   where s.step_title_en = 'Vighneshwara Shodasha Nama Archana';
  if n <> 16 then raise exception 'expected 16 shodasha namas, found %', n; end if;
  -- Every new step is sourced, in Tamil as well as English.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard'
     and (source_ref is null or instruction_ta is null or step_title_ta is null);
  if n > 0 then raise exception '% Ganesha steps are missing a source or Tamil text', n; end if;
  -- A step is a recitation or a list, never both.
  select count(*) into n from public.pooja_steps s
   where s.pooja_id = 'ganesha_standard' and s.mantra_sanskrit is not null
     and exists (select 1 from public.archana_items a where a.pooja_step_id = s.id);
  if n > 0 then raise exception '% steps have both a mantra and an archana list', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;

